const SCENE_OTHER_COLOR='#95a2b1',SCENE_SINGLE_COLOR='#4b86b3';
export function sceneCategories(summary){
 const field=summary?.group_by;
 if(!field)return {field:null,entries:[],keys:[]};
 const rows=Object.entries(summary.groups||{}).filter(([,count])=>typeof count==='number'&&Number.isFinite(count)&&count>=0).sort(([a,x],[b,y])=>y-x||(a<b?-1:a>b?1:0));
 const entries=rows.slice(0,6).map(([key,count])=>({key,name:key===''?'（空文本）':key,count,color:stableSceneColor(field,key)}));
 if(rows.length>6)entries.push({other:true,name:'其他类别（'+(rows.length-6)+'类）',count:rows.slice(6).reduce((sum,[,count])=>sum+count,0),color:SCENE_OTHER_COLOR});
 return {field,entries,keys:rows.map(([key])=>key)};
}
export function sceneFeatureColor(feature,summary,categories=sceneCategories(summary)){
 if(!categories.field)return SCENE_SINGLE_COLOR;
 const frozen=summary.feature_groups,id=String(feature.id);
 let key=null;
 if(frozen&&Object.prototype.hasOwnProperty.call(frozen,id))key=String(frozen[id]);
 else{
  // Old results did not freeze per-feature labels. Only accept an unambiguous
  // match to the archived groups; never infer categories from status wording.
  const raw=feature.properties?.[categories.field];
  if(raw==null)key='(未分组)';
  else if(typeof raw==='boolean')key=raw?'True':'False';
  else if(typeof raw==='number'){
   const candidates=[...new Set([String(raw),Number.isInteger(raw)?raw.toFixed(1):String(raw),raw.toExponential()])].filter(value=>categories.keys.includes(value));
   if(candidates.length===1)key=candidates[0];
  }else key=String(raw);
 }
 return categories.entries.find(entry=>!entry.other&&entry.key===key)?.color||SCENE_OTHER_COLOR;
}
