 if(processing){const summary=processing.summary||{},id=summary.algorithm_id||meta.processing_algorithm,index=summary.index_label||summary.index_id?.toUpperCase()||'指数',method={temporal_median:'时段中位数',temporal_mean:'时段均值',temporal_trend:'时序趋势',otsu_segmentation:'阈值分区'}[id]||'遥感处理',dates=compactObservationCaption(processing);return {title:index+' · '+method,subtitle:dates?'实际观测：'+dates:'实际观测日期见来源报告'};}
