 if(production){const dates=compactObservationCaption(production),index=production.summary?.index?.label||production.provenance?.algorithm?.label||meta.algorithm_id?.toUpperCase()||'光谱指数';return {title:meta.title||index+(meta.production_goal==='change'?'变化':'分布'),subtitle:dates?'实际观测：'+dates:'实际观测日期见来源报告'};}
 if(landcover)return {title:meta.title||'土地覆盖分类参考',subtitle:(meta.source_year||landcover.summary?.reference_year||2021)+'分类产品 · '+(meta.boundary_year||2017)+'参考市界'};
