export function sceneLegendMarkup(record){
 const summary=record.meta.scene_summary||{},categories=sceneCategories(summary),title=summary.scene_name||record.meta.title||'场景台账';
 if(summary.scene_id==='crop_research')return '<div class="legend-reading-board" role="group" aria-label="遥感变化线索图例"><div class="legend-reading-title"><strong>NDVI变化线索</strong><small>'+escapeText(formatProcessingNumber(summary.feature_count)+'个显示图斑 · 显示面积 '+formatProcessingNumber(summary.area_sum_ha)+'公顷')+'</small></div><div class="legend-reading-items"><span><i style="background:#ba7467"></i>指数下降</span><span><i style="background:#438b68"></i>指数上升</span></div><p class="legend-reading-source">'+escapeText('两期共同有效覆盖 '+(Number.isFinite(summary.common_valid_ratio)?(summary.common_valid_ratio*100).toFixed(1)+'%':'未记录')+' · 全市线索，尚未限定耕地；待业务核查'+(summary.truncated?' · 候选超出显示上限，未全部上图':''))+'</p></div>';
 const facts=[formatProcessingNumber(summary.feature_count)+'条记录'];
 if(summary.polygon_feature_count)facts.push('几何面积 '+formatProcessingNumber(summary.area_sum_ha)+' 公顷（未去重）');
 if(summary.line_count){const long=typeof summary.line_length_m==='number'&&summary.line_length_m>=1000;facts.push('累计长度 '+formatProcessingNumber(long?summary.line_length_m/1000:summary.line_length_m)+(long?' 千米':' 米')+'（未去重）');}
 const items=categories.field?(categories.entries.length?categories.entries.map(entry=>'<span><i style="background:'+entry.color+'"></i>'+escapeText(entry.name)+'<b>'+escapeText(entry.count)+'</b></span>').join(''):'<span>类别记录未提供</span>'):'<span><i style="background:'+SCENE_SINGLE_COLOR+'"></i>统一显示</span>';
 const source='上传台账'+(categories.field?' · 按 '+categories.field+' 分类 · 非风险评级':' · 未设置分类字段');
 return '<div class="legend-reading-board" role="group" aria-label="场景图例"><div class="legend-reading-title"><strong>'+escapeText(title)+'</strong><small>'+escapeText(facts.join(' · '))+'</small></div><div class="legend-reading-items">'+items+'</div><p class="legend-reading-source">'+escapeText(source)+'</p></div>';
}

